{"code":"import json,numpy as np
from scipy.optimize import least_squares,minimize
D=json.load(open('evaluations.json')); names=[i['ingredient'] for i in D[0]['recipe']]; D=[d for d in D if all(x['ingredient'] in names for x in d['recipe'])]; X=np.array([[{r['ingredient']:r['fraction'] for r in d['recipe']}.get(n,0) for n in names]for d in D]); y=np.array([d['target_dissimilarity']for d in D]);
# fit squared distance with diagonal curvature, parameters regularized
base=np.array([.575,.095,.13,.06,.035,.045,.03,.015,.015]); scale=np.array([.05,.05,.03,.02,.02,.02,.01,.007,.007]); Z=(X-base)/scale
for reg in [.001,.01,.1]:
 def res(p):
  pred=p[0]+Z@p[1:10]+Z**2@p[10:]
  return np.r_[pred-y*y, np.sqrt(reg)*p[1:10],np.sqrt(reg)*(p[10:]-.015)]
 fit=least_squares(res,np.r_[.01,np.zeros(9),np.ones(9)*.015],bounds=(np.r_[-1,np.full(9,-1),np.zeros(9)],np.ones(19)))
 p=fit.x
 def obj(x):
  z=(x-base)/scale;return p[0]+z@p[1:10]+z*z@p[10:]
 op=minimize(obj,base,bounds=list(zip(base-scale*.7,base+scale*.7)),constraints={'type':'eq','fun':lambda x:x.sum()-1})
 print(reg,op.x,op.fun, 'fit',np.linalg.norm(res(p)))
"}

